-- Inference Lineage data snapshot. Import into a fresh MySQL 8 database.

-- Contains the editable map and paper library metadata, not PDF binaries or credentials.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS map_documents (
      document_id VARCHAR(80) PRIMARY KEY,
      revision BIGINT UNSIGNED NOT NULL,
      payload JSON NOT NULL,
      updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
    ) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS paper_imports (
      id VARCHAR(80) PRIMARY KEY,
      filename VARCHAR(255) NOT NULL,
      status VARCHAR(24) NOT NULL,
      result JSON NULL,
      error_text TEXT NULL,
      created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
      updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
    ) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO map_documents (document_id, revision, payload) VALUES ('main', 163, '{\"nodes\":[{\"id\":\"root\",\"time\":\"\",\"order\":0,\"tagId\":null,\"title\":\"LLM Infra\",\"dabbled\":false,\"parentId\":null,\"description\":\"\"},{\"id\":\"pagedattention\",\"time\":\"2023.9\",\"order\":5,\"tagId\":\"kv-allocation\",\"title\":\"vLLM / PagedAttention\",\"dabbled\":true,\"parentId\":\"root\",\"description\":\"把 KV cache 拆为非连续的逻辑块与物理块，以分页方式降低碎片和重复存储；vLLM 在此基础上扩大可并发处理的请求批次。\"},{\"id\":\"streamingllm\",\"time\":\"2023.9\",\"order\":7,\"tagId\":\"kv-compression\",\"title\":\"StreamingLLM\",\"dabbled\":true,\"parentId\":\"root\",\"description\":\"发现初始 token 的 attention sink 作用；只保留起始与最近位置的 KV，支持长时间流式生成。\"},{\"id\":\"cachegen\",\"time\":\"2023.10\",\"order\":8,\"tagId\":\"kv-compression\",\"title\":\"CacheGen\",\"dabbled\":true,\"parentId\":\"root\",\"description\":\"针对跨请求复用时传输整块 KV cache 的网络开销，编码压缩并流式加载缓存，按网络条件调整压缩率。\"},{\"id\":\"star\",\"time\":\"2025.10\",\"order\":0,\"tagId\":\"cluster-routing\",\"title\":\"STAR\",\"dabbled\":false,\"parentId\":\"distserve\",\"description\":\"DistServe 将 prefill/decode 分离；STAR 在这一部署形态中进一步预测输出长度，动态重排 decode 实例负载。\"},{\"id\":\"span-query\",\"time\":\"2025.11\",\"order\":0,\"tagId\":\"kv-reuse\",\"title\":\"Span Query\",\"dabbled\":false,\"parentId\":\"block-attention\",\"description\":\"承接 Block-Attention 对非前缀块的复用问题，并吸收 CacheBlend 的上下文融合视角；用带交换约束的 span query 统一 chat、RAG 与 Agent 等调用。\"},{\"id\":\"continuum\",\"time\":\"2025.11\",\"order\":0,\"tagId\":\"agent-cache\",\"title\":\"Continuum\",\"dabbled\":true,\"parentId\":\"infercept\",\"description\":\"InferCept 关注外部交互期间的缓存保留；Continuum 进一步根据工具调用时长和排队收益设置 KV TTL，并做任务级调度。\"},{\"id\":\"superinfer\",\"time\":\"2026.1\",\"order\":0,\"tagId\":\"memory-movement\",\"title\":\"SuperInfer\",\"dabbled\":true,\"parentId\":\"pie-memory\",\"description\":\"Pie 在 GH200 上实现 CPU 内存池和 KV 换入；SuperInfer 增加 SLO 感知轮转调度与 NVLink-C2C 双向传输。\"},{\"id\":\"dak\",\"time\":\"2026.4\",\"order\":2,\"tagId\":\"memory-hierarchy\",\"title\":\"DAK\",\"dabbled\":true,\"parentId\":\"flexgen\",\"description\":\"以 FlexGen 一类“先复制到 HBM 再计算”的分层内存方案为对比，DAK 改为 GPU 直接访问远端内存以减少 HBM 争用。\"},{\"id\":\"vericache\",\"time\":\"2026.5\",\"order\":2,\"tagId\":\"accel-codesign\",\"title\":\"VeriCache\",\"dabbled\":true,\"parentId\":\"magicdec\",\"description\":\"以推测解码的起草—验证范式为主线：压缩 KV 负责起草，完整 KV 负责验证。CacheGen 只是论文列举的压缩方法之一，并非直接父节点。\"},{\"id\":\"cachescout\",\"time\":\"2026.8\",\"order\":0,\"tagId\":\"agent-cache\",\"title\":\"CacheScout\",\"dabbled\":true,\"parentId\":\"continuum\",\"description\":\"Continuum 以当前会话的 TTL 保留 KV；CacheScout 与之比较，改用在线学习的 Agent 转移预测，跨工作流决定淘汰与预取。\"},{\"id\":\"oasiskv\",\"time\":\"2026.8\",\"order\":0,\"tagId\":\"kv-prefetch\",\"title\":\"OasisKV\",\"dabbled\":false,\"parentId\":\"infinigen\",\"description\":\"InfiniGen 通过局部预演预测下层重要 KV；OasisKV 在完整 KV 位于 HBM 外的设置中，借推测生成前瞻并异步预取稀疏块。\"},{\"id\":\"sdncm\",\"time\":\"2026.8\",\"order\":1,\"tagId\":\"accel-codesign\",\"title\":\"Strong Drafts Need Compact Memories\",\"dabbled\":true,\"parentId\":\"triforce\",\"description\":\"TriForce 等工作已尝试在长上下文推测解码中缩小草稿侧 KV；本工作为强草稿模型加入可学习的压缩记忆，同时保持目标模型完整 KV 验证。\"},{\"id\":\"composable-cxl\",\"time\":\"2026.9\",\"order\":2,\"tagId\":\"memory-disaggregation\",\"title\":\"Composable CXL Memory\",\"dabbled\":false,\"parentId\":\"vllm-kv-connector\",\"description\":\"借助 vLLM/llm-d 的 KV 连接器，把可组合 CXL 内存作为 Kubernetes 可调度的跨节点共享 KV 层；与 LMCache 是相关的独立方案。\"},{\"id\":\"speculative-decoding\",\"time\":\"2022.11\",\"order\":3,\"tagId\":\"accel-speculative\",\"title\":\"Speculative Decoding\",\"dabbled\":true,\"parentId\":\"root\",\"description\":\"用较轻的模型起草多个 token，再由目标模型并行验证，在保持目标输出分布的条件下加速自回归生成。\"},{\"id\":\"flexgen\",\"time\":\"2023.3\",\"order\":1,\"tagId\":\"memory-hierarchy\",\"title\":\"FlexGen\",\"dabbled\":false,\"parentId\":\"root\",\"description\":\"把权重与 KV 放在 GPU、CPU、磁盘多级内存中，规划放置及传输，建立大模型受限显存推理的内存分层基线。\"},{\"id\":\"sglang\",\"time\":\"2023.12\",\"order\":6,\"tagId\":\"kv-reuse\",\"title\":\"SGLang / RadixAttention\",\"dabbled\":true,\"parentId\":\"root\",\"description\":\"面向结构化多次调用的推理程序，运行时使用 RadixAttention 的基数树管理共享前缀 KV；与 vLLM 构成并行的系统路线。\"},{\"id\":\"distserve\",\"time\":\"2024.1\",\"order\":0,\"tagId\":\"dist-pd\",\"title\":\"DistServe\",\"dabbled\":false,\"parentId\":\"orca\",\"description\":\"将 prefill 和 decode 放到不同 GPU，分别优化 TTFT 与 TPOT，为后续针对解码实例负载的研究提供 PD 分离背景。\"},{\"id\":\"infercept\",\"time\":\"2024.2\",\"order\":4,\"tagId\":\"agent-cache\",\"title\":\"InferCept\",\"dabbled\":false,\"parentId\":\"root\",\"description\":\"针对工具或外部交互造成的推理暂停，保留或迁移请求状态，避免恢复时重复计算上下文；Continuum 明确以它为对比。\"},{\"id\":\"triforce\",\"time\":\"2024.4\",\"order\":3,\"tagId\":\"accel-speculative\",\"title\":\"TriForce\",\"dabbled\":false,\"parentId\":\"speculative-decoding\",\"description\":\"把推测解码扩展到长上下文：用检索式稀疏 KV 构造中间草稿，并让轻量草稿使用 StreamingLLM 缓存；Strong Drafts 后续讨论其草稿侧 KV 代价。\"},{\"id\":\"cacheblend\",\"time\":\"2024.5\",\"order\":0,\"tagId\":\"kv-reuse\",\"title\":\"CacheBlend\",\"dabbled\":false,\"parentId\":\"vllm-apc\",\"description\":\"处理非前缀文本块的 KV 复用问题，通过选择性重算融合已缓存知识；Block-Attention 与 Span Query 都将它作为重要对比。\"},{\"id\":\"infinigen\",\"time\":\"2024.6\",\"order\":1,\"tagId\":\"kv-prefetch\",\"title\":\"InfiniGen\",\"dabbled\":false,\"parentId\":\"flexgen\",\"description\":\"在分层内存推理中提前估计下一层需要的 KV，只从主机内存预取重要条目；OasisKV 将其列为先前的训练免预测方法。\"},{\"id\":\"block-attention\",\"time\":\"2024.9\",\"order\":0,\"tagId\":\"kv-reuse\",\"title\":\"Block-Attention\",\"dabbled\":false,\"parentId\":\"cacheblend\",\"description\":\"将检索文本分块，独立预计算并复用块 KV，以位置重编码与微调处理组合后的注意力；Span Query 将这类块级思路推广到更多调用模式。\"},{\"id\":\"pie-memory\",\"time\":\"2024.11\",\"order\":0,\"tagId\":\"memory-hierarchy\",\"title\":\"Pie (CPU Memory)\",\"dabbled\":false,\"parentId\":\"flexgen\",\"description\":\"在 GH200 上通过透明换入与自适应扩容利用 CPU 内存；SuperInfer 明确将 Pie 称为最相关的前置工作。\"},{\"id\":\"lmcache\",\"time\":\"2025.10\",\"order\":0,\"tagId\":\"dist-kv\",\"title\":\"LMCache\",\"dabbled\":false,\"parentId\":\"vllm-kv-connector\",\"description\":\"将 vLLM、SGLang 的 KV 抽成跨引擎存储与传输层，支持前缀复用和 PD 间缓存移动；Composable CXL 将跨节点共享推进到 CXL 内存。\"},{\"id\":\"orca\",\"time\":\"2022.7\",\"order\":2,\"tagId\":\"request-batching\",\"title\":\"Orca\",\"dabbled\":false,\"parentId\":\"root\",\"description\":\"提出逐迭代调度和选择性批处理，是后续动态批处理及 prefill/decode 调度研究的重要起点。\"},{\"id\":\"specinfer\",\"time\":\"2023.5\",\"order\":0,\"tagId\":\"accel-speculative\",\"title\":\"SpecInfer\",\"dabbled\":false,\"parentId\":\"speculative-decoding\",\"description\":\"把多个草稿序列组织成 token tree，由目标模型一次并行验证；从单条草稿扩展到多候选服务。\"},{\"id\":\"medusa\",\"time\":\"2024.1\",\"order\":0,\"tagId\":\"accel-speculative\",\"title\":\"Medusa\",\"dabbled\":false,\"parentId\":\"specinfer\",\"description\":\"沿用候选树并行验证，但由目标模型上的多个解码头直接提出后续 token，省去独立草稿模型。\"},{\"id\":\"sequoia\",\"time\":\"2024.2\",\"order\":1,\"tagId\":\"accel-speculative\",\"title\":\"Sequoia\",\"dabbled\":false,\"parentId\":\"specinfer\",\"description\":\"将候选树的形状、深度与预算做成硬件感知优化，处理树验证在不同设备和采样温度下的效率。\"},{\"id\":\"draft-verify\",\"time\":\"2023.9\",\"order\":1,\"tagId\":\"accel-speculative\",\"title\":\"Draft & Verify\",\"dabbled\":false,\"parentId\":\"speculative-decoding\",\"description\":\"自推测解码：同一模型跳过部分中间层快速起草，再用完整模型验证，不需要辅助草稿模型。\"},{\"id\":\"layerskip\",\"time\":\"2024.4\",\"order\":0,\"tagId\":\"accel-speculative\",\"title\":\"LayerSkip\",\"dabbled\":false,\"parentId\":\"draft-verify\",\"description\":\"通过层丢弃和提前退出训练，使浅层草稿更可靠；同一模型的后续层继续验证，复用计算与激活。\"},{\"id\":\"eagle\",\"time\":\"2024.1\",\"order\":2,\"tagId\":\"accel-speculative\",\"title\":\"EAGLE\",\"dabbled\":false,\"parentId\":\"speculative-decoding\",\"description\":\"在目标模型高层特征空间起草，并用前移一位的 token 消除特征预测歧义；目标模型保持分布不变。\"},{\"id\":\"eagle-2\",\"time\":\"2024.6\",\"order\":0,\"tagId\":\"accel-speculative\",\"title\":\"EAGLE-2\",\"dabbled\":false,\"parentId\":\"eagle\",\"description\":\"在 EAGLE 的特征草稿上，根据当前上下文的置信度动态分配候选树预算，替代固定树形。\"},{\"id\":\"eagle-3\",\"time\":\"2025.3\",\"order\":0,\"tagId\":\"accel-speculative\",\"title\":\"EAGLE-3\",\"dabbled\":false,\"parentId\":\"eagle-2\",\"description\":\"把 EAGLE 系列改为直接预测 token，并融合目标模型多层特征；改进草稿训练与服务吞吐。\"},{\"id\":\"magicdec\",\"time\":\"2024.8\",\"order\":0,\"tagId\":\"accel-codesign\",\"title\":\"MagicDec\",\"dabbled\":false,\"parentId\":\"triforce\",\"description\":\"受 TriForce 启发，以受限 KV 的自推测草稿加速长上下文，并分析较大 batch 下的延迟与吞吐取舍。\"},{\"id\":\"quantspec\",\"time\":\"2025.2\",\"order\":0,\"tagId\":\"accel-codesign\",\"title\":\"QuantSpec\",\"dabbled\":false,\"parentId\":\"magicdec\",\"description\":\"针对稀疏 KV 草稿可能降低接受率，改用分层 4-bit KV 与 4-bit 权重构造自推测草稿。\"},{\"id\":\"sparsespec\",\"time\":\"2025.12\",\"order\":1,\"tagId\":\"accel-codesign\",\"title\":\"SparseSpec\",\"dabbled\":false,\"parentId\":\"magicdec\",\"description\":\"面向长链推理与批量服务，用验证阶段的注意力信息选取下一轮稀疏草稿 KV，并联合调度、延迟验证和 KV 管理。\"},{\"id\":\"vllm-apc\",\"time\":\"2024.3\",\"order\":0,\"tagId\":\"kv-reuse\",\"title\":\"vLLM Prefix Caching\",\"dabbled\":false,\"parentId\":\"pagedattention\",\"description\":\"将完整 KV 块按前缀与块内容哈希索引，跨请求复用公共前缀；块引用计数和淘汰策略建立在 PagedAttention 的块池上。\"},{\"id\":\"vattention\",\"time\":\"2024.5\",\"order\":1,\"tagId\":\"kv-allocation\",\"title\":\"vAttention\",\"dabbled\":false,\"parentId\":\"pagedattention\",\"description\":\"直接回应 PagedAttention 的非连续虚拟地址开销：用 CUDA 虚拟内存按需映射物理页，同时保持 KV 在虚拟地址中连续。\"},{\"id\":\"vllm-v1\",\"time\":\"2025.1\",\"order\":2,\"tagId\":\"request-batching\",\"title\":\"vLLM V1\",\"dabbled\":false,\"parentId\":\"pagedattention\",\"description\":\"重构调度器、KV 管理器和执行循环；按每请求的 token 预算统一处理分块预填充、前缀缓存与推测解码，并降低 CPU 开销。\"},{\"id\":\"vllm-kv-connector\",\"time\":\"2025\",\"order\":0,\"tagId\":\"dist-kv\",\"title\":\"vLLM KV Connector\",\"dabbled\":false,\"parentId\":\"vllm-v1\",\"description\":\"把外部 KV 读取和写入接入 V1 请求生命周期，为跨实例前缀复用、Prefill/Decode 分离与多层存储提供统一扩展点。\"},{\"id\":\"vllm-offloading\",\"time\":\"2026.1\",\"order\":1,\"tagId\":\"kv-offloading\",\"title\":\"KV Offloading Connector\",\"dabbled\":false,\"parentId\":\"vllm-kv-connector\",\"description\":\"借助异步 KV Connector 将块在 GPU 与 CPU DRAM 间搬运；减少缓存命中时重复预填充，以及被抢占请求的 KV 重算。\"},{\"id\":\"vllm-bidirectional-kv\",\"time\":\"2026.10\",\"order\":3,\"tagId\":\"kv-prefetch\",\"title\":\"Bi-Directional KV Transfer\",\"dabbled\":false,\"parentId\":\"vllm-kv-connector\",\"description\":\"把传统 Prefill→Decode 的单向传输扩为 Decode→Prefill 回传，在多轮 Agent 会话中复用上一轮生成的 KV。\"},{\"id\":\"node-ba84a7ae-3863-4dcb-aff0-25723f670d1a\",\"time\":\"2024.7\",\"order\":1,\"tagId\":\"dist-pd\",\"title\":\"Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving\",\"dabbled\":false,\"parentId\":\"distserve\",\"description\":\"Mooncake 是 Moonshot AI 为 Kimi 构建的以 KVCache 为中心的分离式 LLM 服务架构：将 prefill 与 decoding 集群分离，并把 GPU 集群中闲置的 CPU、DRAM、SSD 组织成分离式 KVCache 池，通过全局调度器 Conductor 在满足 TTFT/TBT SLO 的前提下最大化有效吞吐。针对过载场景提出基于预测的提前拒绝策略，并开源了真实请求 trace。\"}],\"papers\":[{\"id\":\"pagedattention\",\"year\":\"2023.9\",\"notes\":\"\",\"title\":\"Efficient Memory Management for Large Language Model Serving with PagedAttention\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Woosuk Kwon, Zhuohan Li, Siyuan Zhuang 等\",\"codeUrl\":\"https://github.com/vllm-project/vllm\",\"summary\":\"把 KV cache 拆为非连续的逻辑块与物理块，以分页方式降低碎片和重复存储；vLLM 在此基础上扩大可并发处理的请求批次。\",\"abstract\":\"High throughput serving of large language models (LLMs) requires batching sufficiently many requests at a time. However, existing systems struggle because the key-value cache (KV cache) memory for each request is huge and grows and shrinks dynamically. When managed inefficiently, this memory can be significantly wasted by fragmentation and redundant duplication, limiting the batch size. To address this problem, we propose PagedAttention, an attention algorithm inspired by the classical virtual memory and paging techniques in operating systems. On top of it, we build vLLM, an LLM serving system that achieves (1) near-zero waste in KV cache memory and (2) flexible sharing of KV cache within and across requests to further reduce memory usage. Our evaluations show that vLLM improves the throughput of popular LLMs by 2-4 × with the same level of latency compared to the state-of-the-art systems, such as FasterTransformer and Orca. The improvement is more pronounced with longer sequences, larger models, and more complex decoding algorithms. vLLM’s source code is publicly available at https://github.com/vllm-project/vllm.\",\"sourceUrl\":\"https://arxiv.org/abs/2309.06180\"},{\"id\":\"streamingllm\",\"year\":\"2023.9\",\"notes\":\"\",\"title\":\"Efficient Streaming Language Models with Attention Sinks\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Guangxuan Xiao, Yuandong Tian, Beidi Chen 等\",\"codeUrl\":\"https://github.com/mit-han-lab/streaming-llm\",\"summary\":\"发现初始 token 的 attention sink 作用；只保留起始与最近位置的 KV，支持长时间流式生成。\",\"abstract\":\"Deploying Large Language Models (LLMs) in streaming applications such as multi-round dialogue, where long interactions are expected, is urgently needed but poses two major challenges. Firstly, during the decoding stage, caching previous tokens’ Key and Value states (KV) consumes extensive memory. Secondly, popular LLMs cannot generalize to longer texts than the training sequence length. Window attention, where only the most recent KVs are cached, is a natural approach — but we show that it fails when the text length surpasses the cache size. We observe an interesting phenomenon, namely attention sink, that keeping the KV of initial tokens will largely recover the performance of window attention. In this paper, we first demonstrate that the emergence of attention sink is due to the strong attention scores towards initial tokens as a “sink” even if they are not semantically important. Based on the above analysis, we introduce StreamingLLM, an efficient framework that enables LLMs trained with a finite length attention window to generalize to infinite sequence length without any fine-tuning. We show that StreamingLLM can enable Llama-2, MPT, Falcon, and Pythia to perform stable and efficient language modeling with up to 4 million tokens and more. In addition, we discover that adding a placeholder token as a dedicated attention sink during pre-training can further improve streaming deployment. In streaming settings, StreamingLLM outperforms the sliding window recomputation baseline by up to 22.2× speedup. Code and datasets are provided in the link.\",\"sourceUrl\":\"https://arxiv.org/abs/2309.17453\"},{\"id\":\"cachegen\",\"year\":\"2023.10\",\"notes\":\"\",\"title\":\"CacheGen: KV Cache Compression and Streaming for Fast Large Language Model Serving\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Yuhan Liu, Hanchen Li, Yihua Cheng 等\",\"codeUrl\":\"https://github.com/UChi-JCL/CacheGen\",\"summary\":\"针对跨请求复用时传输整块 KV cache 的网络开销，编码压缩并流式加载缓存，按网络条件调整压缩率。\",\"abstract\":\"As large language models (LLMs) take on complex tasks, their inputs are supplemented with longer contexts that incorporate domain knowledge. Yet using long contexts is challenging as nothing can be generated until the whole context is processed by the LLM. While the context-processing delay can be reduced by reusing the KV cache of a context across different inputs, fetching the KV cache, which contains large tensors, over the network can cause high extra network delays. CacheGen is a fast context-loading module for LLM systems. First, CacheGen uses a custom tensor encoder, leveraging KV cache’s distributional properties to encode a KV cache into more compact bitstream representations with negligible decoding overhead, to save bandwidth usage. Second, CacheGen adapts the compression level of different parts of a KV cache to cope with changes in available bandwidth, in order to maintain low context-loading delay and high generation quality. We test CacheGen on popular LLMs and datasets. Compared to the recent systems that reuse the KV cache, CacheGen reduces the KV cache size by 3.5-4.3x and the total delay in fetching and processing contexts by 3.2-3.7x with negligible impact on the LLM response quality. Our code is at: https://github.com/UChi-JCL/CacheGen.\",\"sourceUrl\":\"https://arxiv.org/abs/2310.07240\"},{\"id\":\"star\",\"year\":\"2025.10\",\"notes\":\"\",\"title\":\"STAR: Decode-Phase Rescheduling for LLM Inference\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Zhibin Wang, Zetao Hong, Xue Li 等\",\"codeUrl\":\"\",\"summary\":\"用轻量生成长度预测器估计剩余 decode 工作量，在解码阶段重新调度请求，缓解实例间负载失衡与尾延迟。\",\"abstract\":\"Large Language Model (LLM) inference has emerged as a fundamental paradigm, however, variations in output length cause severe workload imbalance in the decode phase, particularly for long-output reasoning tasks. Existing systems, such as PD disaggregation architectures, rely on static prefill-to-decode scheduling, which often results in SLO violations and OOM failures under evolving decode workloads. In this paper, we propose STAR, a decode rescheduling system powered by length prediction to anticipate future workloads. Our core contributions include: (1) A lightweight and continuous LLM-native prediction method that leverages LLM hidden state to model remaining generation length with high precision (reducing MAE by 49.42%) and low overhead (cutting predictor parameters by 93.28%); (2) A rescheduling solution in decode phase with a dynamic balancing mechanism that integrates current and predicted workloads, reducing P99 TPOT by 75.1% and achieving 2.63×higher goodput. ∗Corresponding author.\",\"sourceUrl\":\"https://arxiv.org/abs/2510.13668\"},{\"id\":\"span-query\",\"year\":\"2025.11\",\"notes\":\"\",\"title\":\"Using Span Queries to Optimize for Cache and Attention Locality\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Paul Castro, Nick Mitchell, Nathan Ordonez 等\",\"codeUrl\":\"\",\"summary\":\"把 chat、RAG、agent 与推理时扩展表示为带交换约束的 span query 表达式树，在 vLLM 上重排请求以提高 KV 缓存与注意力局部性。\",\"abstract\":\"Clients are evolving beyond chat completion, and now include a variety of innovative inference-time scaling and deep reasoning techniques. At the same time, inference servers remain heavily optimized for chat completion and thus largely use linear KV cache strategies. Prior work has shown that large improvements to KV cache hit rate are possible if inference servers evolve towards these more non-linear use cases. However, they offer solutions that are also optimized for a single use case, RAG. In this paper, we demonstrate that chat, RAG, inference-time scaling, and agentic workloads can be expressed as special cases of a more general structure, the span query. The critical distinction that had been assumed by prior work lies in whether the order of the inputs matter — do they commute? In chat, they do not. In RAG, they often do. A span query is an expression tree of inference calls, linked together with commutativity constraints. We describe span query syntax and semantics. We show how they can be automatically optimized to improve KV cache locality. We show how a small change to vLLM (affecting only 492 lines) can enable high-performance execution of span queries. Using this stack, we demonstrate that span queries can achieve 10-20x reductions in TTFT for two distinct non-chat use cases. Finally, we show that span queries can also be optimized to improve attention locality, so as to avoid the so-called lost-in-the-middle problem. We demonstrate that an attention-optimized span query on a 2b parameter model vastly outperforms the accuracy of a stock inference server using an 8b model.\",\"sourceUrl\":\"https://arxiv.org/abs/2511.02749\"},{\"id\":\"continuum\",\"year\":\"2025.11\",\"notes\":\"\",\"title\":\"Continuum: Efficient and Robust Multi-Turn LLM Agent Scheduling with KV Cache Time-to-Live\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Hanchen Li, Runyuan He, Qiuyang Mang 等\",\"codeUrl\":\"\",\"summary\":\"针对 Agent 在工具调用期间暂停的情况，为可复用 KV 设置保留时长，并结合任务级调度，减少多轮请求重算。\",\"abstract\":\"KV cache management is essential for efficient LLM inference. To maximize utilization, existing inference engines evict finished requests’ KV cache if new requests are waiting. This policy breaks for agentic workloads, which interleave LLM calls with tools, introducing pauses that prevent effective KV reuse across turns. Since many tool calls have much shorter durations than human response multi-turn chatbot, it would be promising to retain the KV cache in during these tools. However, many challenges remain. First, we need to consider both the potential cost of recomputation or reloading (if offloading enabled) as well as the increasing queueing delays after eviction from GPU. Second, due to the internal variance of tool call durations, the method needs to remain robust under limited predictability of tool call durations. We present Continuum, a serving system to optimize job completion time for multi-turn agent workloads by introducing time-to-live mechanism for KV cache retention. For requests that generate tool calls, Continuum selectively pins the KV cache in GPU memory with a time-to-live value determined by the reload cost and potential queueing delay induced by eviction. When the TTL expires, the KV cache can be automatically evicted to free up GPU memory, providing robust performance under edge cases. When combined with programlevel first-come-first-serve, Continuum preserves multi-turn continuity, and reduces delay for agentic workflows. Evaluations on real-world agents (SWE-Bench, BFCL, OpenHand) with Llama-3.1 8B/70B, Gemma-3 12B, and GLM-4.5 355B shows that Continuum improves the average job completion times by over 8x while improving throughput.\",\"sourceUrl\":\"https://arxiv.org/abs/2511.02230\"},{\"id\":\"superinfer\",\"year\":\"2026.1\",\"notes\":\"\",\"title\":\"SuperInfer: SLO-Aware Rotary Scheduling and Memory Management for LLM Inference on Superchips\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Jiahuan Yu, Mingtao Hu, Zichao Lin, Minjia Zhang\",\"codeUrl\":\"https://github.com/Supercomputing-System-AI-Lab/SuperInfer\",\"summary\":\"面向 GH200 等 CPU/GPU 紧耦合芯片，结合 SLO 感知轮转调度与 KV 双向传输，在扩大有效内存时控制请求等待。\",\"abstract\":\"Large Language Model (LLM) serving faces a fundamental tension between stringent latency Service Level Objectives (SLOs) and limited GPU memory capacity. When high request rates exhaust the KV cache budget, existing LLM inference systems often suffer severe head-of-line (HOL) blocking. While prior work explored PCIe-based offloading, these approaches cannot sustain responsiveness under high request rates, often failing to meet tight Time-To-First-Token (TTFT) and Time-Between-Tokens (TBT) SLOs. We present SuperInfer, a high-performance LLM inference system designed for emerging Superchips (e.g., NVIDIA GH200) with tightly coupled GPU-CPU architecture via NVLink-C2C. SuperInfer introduces RotaSched, the first proactive, SLO-aware rotary scheduler that rotates requests to maintain responsiveness on Superchips, and DuplexKV, an optimized rotation engine that enables full-duplex transfer over NVLink-C2C. Evaluations on GH200 using various models and datasets show that SuperInfer improves TTFT SLO attainment rates by up to 74.7% while maintaining comparable TBT and throughput compared to state-of-the-art systems, demonstrating that SLO-aware scheduling and memory co-design unlocks the full potential of Superchips for responsive LLM serving. Code is available at https://github.com/Supercomputing-System-AI-Lab/SuperInfer.\",\"sourceUrl\":\"https://arxiv.org/abs/2601.20309\"},{\"id\":\"mac-attention\",\"year\":\"2026.4\",\"notes\":\"\",\"title\":\"MAC-Attention: a Match-Amend-Complete Scheme for Fast and Accurate Attention Computation\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Jinghan Yao, Sam Adé Jacobs, Walid Krichene 等\",\"codeUrl\":\"https://github.com/YJHMITWEB/MAC-Attention\",\"summary\":\"复用相近查询的既有注意力计算，并修正边界与补算新 KV，在保留完整 KV 可访问性的同时降低长上下文解码读取量。\",\"abstract\":\"Long-context decoding in LLMs is IO-bound: each token re-reads an ever-growing KV cache. Prior accelerations cut bytes via compression (lowering fidelity) or selection/eviction (restricting what remains accessible), which can degrade delayed recall and long-form generation. We introduce MAC-Attention, a fidelity- and access-preserving alternative that accelerates decode by reusing prior attention computations for semantically similar recent queries. It starts with a match stage that performs pre-RoPE L2 matching over a short local window; an amend stage rectifies the reused attention by recomputing a small band near the match boundary; and a complete stage fuses the rectified results with a fresh attention computed on the KV tail, via a numerically stable merge. On a match hit, the compute and bandwidth complexity is constant regardless of the context length. The method is model-agnostic, and composes with IO-aware kernels, paged-KV managers, and MQA/GQA. Across LongBench v2 (120K), RULER (120K), and LongGenBench (16K continuous generation), compared to latest FlashInfer library, MAC-Attention reduces KV accesses by up to 99%, cuts token generation latency by over 60% at 128K, and achieves over 14.3× attention-phase speedups (up to 2.6× end-to-end), while maintaining full-attention quality. By reusing computation, MAC-Attention delivers long-context inference that is both fast and faithful. Code is available here.\",\"sourceUrl\":\"https://arxiv.org/abs/2604.00235\"},{\"id\":\"dak\",\"year\":\"2026.4\",\"notes\":\"\",\"title\":\"DAK: Direct-Access-Enabled GPU Memory Offloading with Optimal Efficiency for LLM Inference\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Shouxu Lin, Zhiyuan Guo, Jiaxin Lin\",\"codeUrl\":\"https://github.com/shouxulin/DirectAccessKernel\",\"summary\":\"让 GPU 直接访问远端内存，绕过先搬入 HBM 的传统预取路径；结合访存调度，减少 HBM 争用与流水线空隙。\",\"abstract\":\"LLM inference is constrained by GPU memory capacity and bandwidth. Tiered memory architectures mitigate this by allowing the GPU to offload memory to the remote tier. However, existing memory offloading frameworks rely on prefetching data into local GPU HBM. This approach underutilizes system resources by introducing HBM contention, squandering memory capacity, and creating pipeline bubbles. We show that enabling direct GPU access to remote memory significantly outperforms prefetching, achieving optimal aggregate system bandwidth. We propose DAK, an end-to-end directaccess memory offloading framework that repurposes the Tensor Memory Accelerator (TMA) to asynchronously fetch offloaded weights and KV caches directly from remote memory into GPU shared memory (SMEM). To maximize remote access performance, DAK introduces a greedy algorithm to determine optimal per-operation offloading ratios, alongside active congestion control and TMA multicast to eliminate interconnect bottlenecks and read amplification. Evaluations across diverse architectures show that DAK achieves nearoptimal bandwidth aggregation, with up to 3× performance gains on NVLink-C2C and 1.8× on PCIe systems compared to state-of-the-art memory offloading baselines.\",\"sourceUrl\":\"https://arxiv.org/abs/2604.26074\"},{\"id\":\"vericache\",\"year\":\"2026.5\",\"notes\":\"\",\"title\":\"VeriCache: Turning Lossy KV Cache into Lossless LLM Inference\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Jiayi Yao, Samuel Shen, Kuntai Du 等\",\"codeUrl\":\"\",\"summary\":\"用压缩 KV 进行草稿生成，再由完整 KV 验证输出；把完整缓存放在 GPU 外并交错传输与计算，使有损压缩服务于无损推理。\",\"abstract\":\"The large size of the KV cache has become a major bottleneck for serving LLMs with increasing context lengths. In response, many KV cache compression methods, such as token dropping and quantization, have been proposed. However, almost all of these methods are inherently lossy— despite minimal accuracy degradation for short outputs, their outputs increasingly diverge from full-KV-cache outputs as more tokens are decoded, which leads to catastrophic failures in code generation and tool calling. We present VeriCache, the first inference framework that ensures thesameoutput as full-KV-cache decoding but largely preserves the high decoding throughput of arangeof KV cache compression algorithms. VeriCache uses the compressed KV cache to draft tokens, then verifies them against the full KV cache. While it may seem like just speculative decoding, VeriCache requires addressing a key system challenge to work—keeping the full KV cache out of GPU memory andminimizing the overhead of swapping it in for verification. The insight is two-fold: (1) compressed-KV decoding can be parallelized with full-KV swap, because one is HBMbandwidth-bound and the other is PCIe/network-bound, and (2) the compressed KV cache often produces output similar to the full KV cache, allowing a long drafting horizon to amortize each full-KV swap. VeriCache applies to both long-context decoding and remote prefix caching, supports a broad family of token-dropping and quantization methods through a uniform compressor interface, and composes with traditional speculative decoding. Experimental results show that VeriCache achieves up to4 × higher throughput than full-KV inference while producing identical outputs.\",\"sourceUrl\":\"https://arxiv.org/abs/2605.17613\"},{\"id\":\"cachescout\",\"year\":\"2026.8\",\"notes\":\"\",\"title\":\"Learning Agent Execution for KV-Cache Management in Agentic Serving\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Rui Zhang, Chaeeun Kim, Shaoting Feng 等\",\"codeUrl\":\"\",\"summary\":\"在线学习 Agent 执行阶段之间的转移，依据未来复用概率驱动 KV 淘汰与预取；与 Continuum 一样面向 Agent 多轮缓存，但进一步利用工作流语义。\",\"abstract\":\"Multi-agent LLM systems have emerged as an important deployment paradigm for AI services, where each user request is decomposed into a sequence of specialized agents. Across these workflows, every agent repeatedly executes a fixed context consisting of system prompts, tool definitions, and few-shot examples, creating substantial opportunities for KV-cache reuse. Existing LLM serving systems, however, manage KV-cache reactively using prefix caching and recency-based replacement, causing reusable agent contexts to be evicted before their next invocation and forcing repeated recomputation. We presentCacheScout, an agent-aware KV-cache runtime layer for multi-agent LLM serving. The key insight is that future KV-cache reuse is governed by agent execution semantics rather than cache recency alone.CacheScoutcaptures these semantics by learning agent execution transitions online, without requiring predefined workflow graphs or offline training, and uses the learned execution model to guide both cache eviction and proactive prefetching while leaving the serving critical path unchanged. We implementCacheScouton top of vLLM. Across representative real-world multi-agent workloads,CacheScoutimproves KV-cache hit rate by 10–18 percentage points, reduces mean TTFT by 18–45%, lowers mean per-turn latency by 29–38%, and increases peak throughput by up to 57%. These benefits also generalize to larger models, reducing TTFT by up to 54% while sustaining 37% higher throughput.\",\"sourceUrl\":\"https://arxiv.org/abs/2608.14624\"},{\"id\":\"oasiskv\",\"year\":\"2026.8\",\"notes\":\"\",\"title\":\"OasisKV: Scaling In-Decode KV Cache Beyond HBM with Lookahead Sparse Prefetching\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Can Xiao, Sukmin Cho, Junbong We 等\",\"codeUrl\":\"\",\"summary\":\"把完整 KV 移至 HBM 之外，利用推测生成的前瞻信息异步预取下一步可能用到的稀疏 KV，扩大解码时的有效缓存容量。\",\"abstract\":\"Large language model (LLM) inference serving is increasingly constrained by memory rather than compute. As longcontext and long-form reasoning workloads become more prevalent, the key-value (KV) cache dominates both memory footprint and memory traffic during LLM token generation,i.e., decode. In particular, HBM capacity has become a scarce and costly resource that heavily limits inference batch size and system throughput. This paper presentsOasisKV, a memory-centric LLM inference system design that alleviates HBM capacity pressure by decoupling full KV-cache storage from HBM during LLM decoding. Because decode-time attention is naturally sparse, OasisKV keeps only the KV entries of the most relevant tokens in HBMs for attention computation. We observe that future important tokens can be predicted accurately in advance using lookahead tokens drafted by speculative decoding (SD). OasisKV employs an efficient attention background pipeline to identify important KV blocks. They are then prefetched from higher-capacity memory tiers (e.g., host or remote memory) and staged in HBMs before being used in the next decode step. We implement OasisKV based on vLLM. The lookahead prediction is accurate enough to keep accuracy within 0.7 points of full attention under a 2,048-token KV budget. This lets OasisKV turn sparsity into throughput gain:1 .69× over dense vLLM on the reasoning workload at 0.1 points of accuracy loss, and up to2 .1× on multi-GPU long-context serving. Under prefill–decode disaggregation, OasisKV reaches about 2× dense throughput while admitting each request with ∗Both authors contributed equally to this work. Part of this work was completed during their internships at Microsoft Research. †Corresponding authors. 6.5–9.7× less KV and holding2 .2-2.6less decode-node host memory than full KV transfer.\",\"sourceUrl\":\"https://arxiv.org/abs/2608.08097\"},{\"id\":\"sdncm\",\"year\":\"2026.8\",\"notes\":\"\",\"title\":\"Strong Drafts Need Compact Memories: Long-Context Speculative Decoding with Compressed KV Cache\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Tong Yuan, Chengxi Liao, Zeyi Wen\",\"codeUrl\":\"\",\"summary\":\"给强草稿模型构建压缩的草稿侧 KV 记忆，保留远距离信息与精确近期上下文；目标模型仍用完整 KV 验证，保持推测解码的输出一致性。\",\"abstract\":\"Long-context LLM applications such as document summarization and multi-turn agents require generation from prefixes spanning tens of thousands of tokens, making decoding latency a major bottleneck. Speculative decoding (SD) reduces latency without changing model outputs, but its speedup depends on both accepted draft tokens and draft-step latency: Lightweight drafts are fast but lack the capacity to capture long-range dependencies, whereas strong independent drafts recover acceptance but incur growing KV-access cost at long prefixes. We introduce memory-augmented drafting for longcontext SD, equipping a strong independent draft with compressed draft-side KV memory: A lightweight adaptor constructs and incrementally updates this memory to retain distant information and exact recent context. The target verifier retains its full KV cache and applies the standard accept/reject rule, preserving SD’s lossless guarantee. Experiments on Llama 3.1- 8B and 70B targets at prefix lengths up to 32K show that our method reduces draft-side memory by over 70%. It achieves speedups of up to 2.08× and 3.33×, respectively, over autoregressive decoding.\",\"sourceUrl\":\"https://arxiv.org/abs/2608.30252\"},{\"id\":\"composable-cxl\",\"year\":\"2026.9\",\"notes\":\"关系：论文将 LMCache 列为相关的外部 KV 缓存工作；本方案接入 vLLM/llm-d 连接器，并用 Kubernetes DRA 管理可组合 CXL 区域，不是对 LMCache 实现的直接延续。\\n读法：区分内存分离与 Prefill/Decode 分离；论文 v1 只验证前者。\\n取舍：需要 CXL 设备与可组合内存基础设施，结果属于可行性研究。\",\"title\":\"Composable CXL Memory as a Kubernetes-Native Shared Memory for LLM Serving: A Feasibility Study on Seagate Composable Memory Appliance\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Hongjian Fan, Kevin Zhang, David Habinsky, Sean Dykstra\",\"codeUrl\":\"\",\"summary\":\"把可组合 CXL 内存作为 Kubernetes 中可调度的共享层，并通过 vLLM/llm-d 连接器跨节点复用前缀 KV；论文定位为可行性研究。\",\"abstract\":\"We present a Kubernetes Dynamic Resource Allocation (DRA) driver that makes composable CXL memory a schedulable cluster resource, and evaluate the resulting shared-memory tier for cross-node KV-cache reuse in LLM serving. The driver composes CXL regions on demand, materializes them as DAX devices on each participating host, and injects them into pods under a single Container Device Interface (CDI) name so that pods on different nodes access the same physical region. A shared-memory connector for vLLM/llm-d uses that region as a KV-cache tier with a slot directory embedded inside the shared medium, which eliminates the need for an external metadata service. On a two-node cluster with a 512GiB CXL appliance and Qwen2.5-7B-Instruct, cross-node prefix reuse reduces TTFT by 5.5×–36.6× at an external hit rate of 95.4–99.5%, while node-local tiers (GPU prefix caching, CPU-DRAM offload) fall back to full recompute. The sharing gap, defined as the latency ratio between cross-node and same-node reuse, is 1–4%, indicating that cross-node reuse incurs little additional latency relative to same-node reuse on our testbed. Both replicas run full engines; the study demonstrates memory disaggregation rather than prefill/decode disaggregation. We report this as a feasibility study rather than a performance evaluation.\",\"sourceUrl\":\"https://arxiv.org/abs/2609.10790\"},{\"id\":\"flashattention\",\"year\":\"2022.5\",\"notes\":\"\",\"title\":\"FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Tri Dao, Daniel Y. Fu, Stefano Ermon 等\",\"codeUrl\":\"\",\"summary\":\"通过分块与片上 SRAM 复用减少 HBM 读写，提出面向 I/O 成本的精确注意力实现。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2205.14135\"},{\"id\":\"speculative-decoding\",\"year\":\"2022.11\",\"notes\":\"\",\"title\":\"Fast Inference from Transformers via Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yaniv Leviathan, Matan Kalman, Yossi Matias\",\"codeUrl\":\"\",\"summary\":\"用较轻的模型起草多个 token，再由目标模型并行验证，在保持目标输出分布的条件下加速自回归生成。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2211.17192\"},{\"id\":\"flexgen\",\"year\":\"2023.3\",\"notes\":\"\",\"title\":\"FlexGen: High-Throughput Generative Inference of Large Language Models with a Single GPU\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Ying Sheng, Lianmin Zheng, Binhang Yuan 等\",\"codeUrl\":\"https://github.com/FMInference/FlexGen\",\"summary\":\"把权重与 KV 放在 GPU、CPU、磁盘多级内存中，规划放置及传输，建立大模型受限显存推理的内存分层基线。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2303.06865\"},{\"id\":\"sglang\",\"year\":\"2023.12\",\"notes\":\"\",\"title\":\"SGLang: Efficient Execution of Structured Language Model Programs\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Lianmin Zheng, Liangsheng Yin, Zhiqiang Xie 等\",\"codeUrl\":\"https://github.com/sgl-project/sglang\",\"summary\":\"面向结构化多次调用的推理程序，运行时使用 RadixAttention 的基数树管理共享前缀 KV；与 vLLM 构成并行的系统路线。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2312.07104\"},{\"id\":\"distserve\",\"year\":\"2024.1\",\"notes\":\"\",\"title\":\"DistServe: Disaggregating Prefill and Decoding for Goodput-optimized Large Language Model Serving\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yinmin Zhong, Shengyu Liu, Junda Chen 等\",\"codeUrl\":\"\",\"summary\":\"将 prefill 和 decode 放到不同 GPU，分别优化 TTFT 与 TPOT，为后续针对解码实例负载的研究提供 PD 分离背景。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2401.09670\"},{\"id\":\"infercept\",\"year\":\"2024.2\",\"notes\":\"\",\"title\":\"InferCept: Efficient Intercept Support for Augmented Large Language Model Inference\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Reyna Abhyankar, Zijian He, Vikranth Srivatsa 等\",\"codeUrl\":\"\",\"summary\":\"针对工具或外部交互造成的推理暂停，保留或迁移请求状态，避免恢复时重复计算上下文；Continuum 明确以它为对比。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2402.01869\"},{\"id\":\"triforce\",\"year\":\"2024.4\",\"notes\":\"\",\"title\":\"TriForce: Lossless Acceleration of Long Sequence Generation with Hierarchical Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Hanshi Sun, Zhuoming Chen, Xinyu Yang 等\",\"codeUrl\":\"https://github.com/Infini-AI-Lab/TriForce\",\"summary\":\"把推测解码扩展到长上下文：用检索式稀疏 KV 构造中间草稿，并让轻量草稿使用 StreamingLLM 缓存；Strong Drafts 后续讨论其草稿侧 KV 代价。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2404.11912\"},{\"id\":\"cacheblend\",\"year\":\"2024.5\",\"notes\":\"\",\"title\":\"CacheBlend: Fast Large Language Model Serving for RAG with Cached Knowledge Fusion\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Jiayi Yao, Hanchen Li, Yuhan Liu 等\",\"codeUrl\":\"\",\"summary\":\"处理非前缀文本块的 KV 复用问题，通过选择性重算融合已缓存知识；Block-Attention 与 Span Query 都将它作为重要对比。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2405.16444\"},{\"id\":\"infinigen\",\"year\":\"2024.6\",\"notes\":\"\",\"title\":\"InfiniGen: Efficient Generative Inference of Large Language Models with Dynamic KV Cache Management\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Wonbeom Lee, Jungi Lee, Junghwan Seo, Jaewoong Sim\",\"codeUrl\":\"\",\"summary\":\"在分层内存推理中提前估计下一层需要的 KV，只从主机内存预取重要条目；OasisKV 将其列为先前的训练免预测方法。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2406.19707\"},{\"id\":\"block-attention\",\"year\":\"2024.9\",\"notes\":\"\",\"title\":\"Block-Attention for Efficient Prefilling\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Dongyang Ma, Yan Wang, Tian Lan\",\"codeUrl\":\"\",\"summary\":\"将检索文本分块，独立预计算并复用块 KV，以位置重编码与微调处理组合后的注意力；Span Query 将这类块级思路推广到更多调用模式。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2409.15355\"},{\"id\":\"pie-memory\",\"year\":\"2024.11\",\"notes\":\"\",\"title\":\"Pie: Pooling CPU Memory for LLM Inference\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yi Xu, Ziming Mao, Xiangxi Mo 等\",\"codeUrl\":\"\",\"summary\":\"在 GH200 上通过透明换入与自适应扩容利用 CPU 内存；SuperInfer 明确将 Pie 称为最相关的前置工作。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2411.09317\"},{\"id\":\"lmcache\",\"year\":\"2025.10\",\"notes\":\"\",\"title\":\"LMCache: An Efficient KV Cache Layer for Enterprise-Scale LLM Inference\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yihua Cheng, Yuhan Liu, Jiayi Yao 等\",\"codeUrl\":\"https://github.com/LMCache/LMCache\",\"summary\":\"将 vLLM、SGLang 的 KV 抽成跨引擎存储与传输层，支持前缀复用和 PD 间缓存移动；Composable CXL 将跨节点共享推进到 CXL 内存。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2510.09665\"},{\"id\":\"orca\",\"year\":\"2022.7\",\"notes\":\"\",\"title\":\"Orca: A Distributed Serving System for Transformer-Based Generative Models\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Gyeong-In Yu, Joo Seong Jeong, Geon-Woo Kim 等\",\"codeUrl\":\"\",\"summary\":\"提出逐迭代调度和选择性批处理，是后续动态批处理及 prefill/decode 调度研究的重要起点。\",\"abstract\":\"\",\"sourceUrl\":\"https://www.usenix.org/conference/osdi22/presentation/yu\"},{\"id\":\"specinfer\",\"year\":\"2023.5\",\"notes\":\"关系：沿用基础推测解码的草稿—验证框架，改变候选结构与批量验证方式。\\n读法：重点看 token tree 构造、验证掩码、分布保持证明及服务端延迟拆解。\\n取舍：候选树更大时验证成本与草稿命中率需共同权衡。\",\"title\":\"SpecInfer: Accelerating Generative Large Language Model Serving with Tree-based Speculative Inference and Verification\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Xupeng Miao 等\",\"codeUrl\":\"\",\"summary\":\"将多个小模型提出的候选序列合并为 token tree，通过树式并行解码一次验证多个分支，服务场景下保持目标模型生成质量。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2305.09781\"},{\"id\":\"medusa\",\"year\":\"2024.1\",\"notes\":\"关系：引用 SpecInfer 的候选树验证，但草稿来源改为多解码头。\\n读法：区分 Medusa-1 与联合微调主模型的 Medusa-2；精确分布/质量保证要按具体接受规则判断。\\n取舍：省去单独草稿模型，仍需训练或微调额外解码头。\",\"title\":\"Medusa: Simple LLM Inference Acceleration Framework with Multiple Decoding Heads\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Tianle Cai 等\",\"codeUrl\":\"https://github.com/FasterDecoding/Medusa\",\"summary\":\"给主模型添加多个解码头预测后续 token，组成候选树并用树式注意力并行验证。Medusa-1 冻结主模型，报告无质量损失的加速。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2401.10774\"},{\"id\":\"sequoia\",\"year\":\"2024.2\",\"notes\":\"关系：延续树状候选验证，关注候选预算如何映射到具体硬件。\\n读法：关注树优化目标、草稿接受概率估计、GPU/卸载场景差异。\\n取舍：更复杂的树可能提高每轮接受量，也增加验证计算和调参成本。\",\"title\":\"Sequoia: Scalable, Robust, and Hardware-aware Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Zhuoming Chen 等\",\"codeUrl\":\"\",\"summary\":\"使用动态规划设计候选树，并按硬件自动选择树大小与深度；还提出适应不同采样温度的采样和验证方式。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2402.12374\"},{\"id\":\"draft-verify\",\"year\":\"2023.9\",\"notes\":\"关系：把基础推测解码中的独立草稿模型替换成原模型的便宜执行路径。\\n读法：比较被跳过层的选择、草稿接受率、无额外训练时的速度收益。\\n取舍：起草仍需运行同一模型的大部分计算。\",\"title\":\"Draft & Verify: Lossless Large Language Model Acceleration via Self-Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Jun Zhang 等\",\"codeUrl\":\"\",\"summary\":\"在同一个 LLM 内跳过部分中间层起草，再由完整模型一次验证，避免独立草稿模型及其额外显存。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2309.08168\"},{\"id\":\"layerskip\",\"year\":\"2024.4\",\"notes\":\"关系：沿自推测解码的同模型草稿路线，提高提前退出草稿的可用性。\\n读法：看训练改动、浅层预测准确率、验证复用与端到端加速。\\n取舍：需要专门训练或继续训练模型。\",\"title\":\"LayerSkip: Enabling Early Exit Inference and Self-Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Mostafa Elhoushi 等\",\"codeUrl\":\"https://github.com/facebookresearch/LayerSkip\",\"summary\":\"训练时采用层丢弃与提前退出损失，使浅层预测更可靠；推理时浅层起草、其余层验证并复用中间激活。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2404.16710\"},{\"id\":\"eagle\",\"year\":\"2024.1\",\"notes\":\"关系：另辟高层特征草稿路线，后续 EAGLE-2/3 在此基础上改树形和训练。\\n读法：弄清特征预测与 token 预测的差别、草稿开销与接受率。\\n取舍：通常需要额外草稿模块及训练。\",\"title\":\"EAGLE: Speculative Sampling Requires Rethinking Feature Uncertainty\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yuhui Li 等\",\"codeUrl\":\"https://github.com/SafeAILab/EAGLE\",\"summary\":\"把草稿建模移到目标模型倒数第二层特征空间，配合前移 token 缓解特征预测歧义，然后由目标模型验证。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2401.15077\"},{\"id\":\"eagle-2\",\"year\":\"2024.6\",\"notes\":\"关系：直接延续 EAGLE 的特征草稿，将优化重点转向每轮树结构。\\n读法：关注树扩展策略、置信度校准与验证预算。\\n取舍：动态构树有额外控制开销，收益依赖置信度估计。\",\"title\":\"EAGLE-2: Faster Inference of Language Models with Dynamic Draft Trees\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yuhui Li 等\",\"codeUrl\":\"https://github.com/SafeAILab/EAGLE\",\"summary\":\"在 EAGLE 上用草稿置信度估计候选接受率，随上下文动态构建候选树，而非一直使用固定拓扑。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2406.16858\"},{\"id\":\"eagle-3\",\"year\":\"2025.3\",\"notes\":\"关系：EAGLE-2 之后的同一方法系列；论文报告相对 EAGLE-2 的加速改进与 SGLang 批量吞吐结果。\\n读法：比较特征预测与直接 token 预测、训练时测试和多层特征融合的消融。\\n取舍：性能更依赖草稿模型的训练与目标模型特征接口。\",\"title\":\"EAGLE-3: Scaling up Inference Acceleration of Large Language Models via Training-Time Test\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yuhui Li 等\",\"codeUrl\":\"https://github.com/SafeAILab/EAGLE\",\"summary\":\"改为直接预测 token，利用多层特征融合和训练时测试，使草稿模型更能从训练数据扩展中受益。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2503.01840\"},{\"id\":\"magicdec\",\"year\":\"2024.8\",\"notes\":\"关系：论文明确写明受 TriForce 启发，重点从小 batch 长上下文转向较大 batch 的服务吞吐。\\n读法：对照 The Synergy of Speculative Decoding and Batching 的结论，关注瓶颈从权重搬运转向 KV 搬运的条件。\\n取舍：收益依赖上下文长度、batch 大小和草稿 KV 预算。\",\"title\":\"MagicDec: Breaking the Latency-Throughput Tradeoff for Long Context Generation with Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Ranajoy Sadhukhan 等\",\"codeUrl\":\"https://github.com/Infini-AI-Lab/MagicDec\",\"summary\":\"利用受限 KV 的自推测草稿处理长上下文；分析批量大小与上下文长度，展示大 batch 时仍可通过草稿阶段减少 KV 带宽。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2408.11049\"},{\"id\":\"quantspec\",\"year\":\"2025.2\",\"notes\":\"关系：论文直接讨论 TriForce、MagicDec 的稀疏 KV 草稿，提出量化 KV 作为另一种受限记忆路径。\\n读法：重点看层级量化、KV 更新、接受率和端到端显存/时延。\\n取舍：量化误差可能影响草稿与目标模型匹配；不能只看 KV 压缩率。\",\"title\":\"QuantSpec: Self-Speculative Decoding with Hierarchical Quantized KV Cache\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Rishabh Tiwari 等\",\"codeUrl\":\"\",\"summary\":\"同模型草稿采用分层 4-bit KV 与 4-bit 权重，在长上下文中减小草稿侧访存，同时缓解单纯稀疏 KV 造成的接受率下降。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2502.10424\"},{\"id\":\"sparsespec\",\"year\":\"2025.12\",\"notes\":\"关系：论文直接比较 MagicDec 与 TriForce，并指出静态稀疏草稿难适应不断增长的推理输出。\\n读法：看输入长上下文与长输出的瓶颈差异、PillarAttn、CPU/GPU 重叠与吞吐评估。\\n取舍：核心收益针对长输出且注意力访存主导的负载。\",\"title\":\"Accelerating Large-Scale Reasoning Model Inference with Sparse Self-Speculative Decoding\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Yilong Zhao 等\",\"codeUrl\":\"\",\"summary\":\"针对长链推理输出，以 PillarAttn 复用验证阶段的注意力信息选关键 KV 供下一轮草稿，并将批量调度、延迟验证、KV 管理一起设计。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2512.01278\"},{\"id\":\"speculative-sampling\",\"year\":\"2023.2\",\"notes\":\"位置：链接到基础节点作为并行奠基工作；树边不表示其是 Leviathan 工作的直接后继。\\n读法：对照两篇论文的接受/拒绝采样推导和实现假设。\",\"title\":\"Accelerating Large Language Model Decoding with Speculative Sampling\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Charlie Chen 等\",\"codeUrl\":\"\",\"summary\":\"与基础推测解码同期的独立工作：用小模型起草、目标模型并行检验及拒绝采样，在保持目标分布的前提下加速生成。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2302.01318\"},{\"id\":\"speculation-batching\",\"year\":\"2023.10\",\"notes\":\"位置：作为系统取舍论文链接到基础节点；与 MagicDec 的长上下文大 batch 分析形成对照。\\n读法：重点看 batch、推测长度、GPU 利用率和端到端吞吐的关系。\",\"title\":\"The Synergy of Speculative Decoding and Batching in Serving Large Language Models\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Qidong Su, Christina Giannoula, Gennady Pekhimenko\",\"codeUrl\":\"\",\"summary\":\"实测推测解码与批量服务的相互作用，指出最优推测长度依赖 batch 大小，并提出自适应选择策略。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2310.18813\"},{\"id\":\"vllm-apc\",\"year\":\"2024.3\",\"notes\":\"资料类型：vLLM 原始设计 RFC，2024.1 提出，相关实现于 2024.3 合入；节点时间按实现完成月标注。\\n关系：在 PagedAttention 块池上增加跨请求的内容寻址复用。\\n读法：先看块哈希由前缀和当前块 token 决定，再看引用计数、命中、淘汰和部分块限制。\\n边界：精确匹配公共前缀；非前缀块复用留给 CacheBlend 等后续工作。\",\"title\":\"[RFC] Automatic Prefix Caching\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Zhuohan Li / vLLM contributors\",\"codeUrl\":\"https://github.com/vllm-project/vllm\",\"summary\":\"在 vLLM 的逻辑块与物理块之间加入哈希索引；完整块跨请求保留并按引用计数与 LRU 等策略淘汰，让相同前缀免重复预填充。\",\"abstract\":\"\",\"sourceUrl\":\"https://github.com/vllm-project/vllm/issues/2614\"},{\"id\":\"vattention\",\"year\":\"2024.5\",\"notes\":\"关系：论文明确以 PagedAttention 为对照，属于对分页 KV 地址布局的反向设计，而非 vLLM 的版本更新。\\n读法：重点比较逻辑/物理连续性、CUDA VMM 映射成本、内核兼容性与真实吞吐。\\n取舍：需要 CUDA 虚拟内存机制，也需权衡映射粒度与系统开销。\",\"title\":\"vAttention: Dynamic Memory Management for Serving LLMs without PagedAttention\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Ramya Prabhu 等\",\"codeUrl\":\"\",\"summary\":\"把 KV 物理内存按需分配与连续虚拟地址解耦；相比 PagedAttention 的非连续虚拟块，现有连续地址注意力内核可更直接使用。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2405.04437\"},{\"id\":\"vllm-v1\",\"year\":\"2025.1\",\"notes\":\"资料类型：官方工程设计文章，非学术论文。\\n关系：直接继承原 vLLM/PagedAttention，但将优化从单一 KV 内存管理扩展为统一运行时。\\n读法：重点看 {request_id: num_tokens} 调度表示、零开销前缀缓存、持久批处理、进程边界及 CPU/GPU 重叠。\\n取舍：V1 的结果包含多项协同优化，不宜把性能增益全归给 PagedAttention。\",\"title\":\"vLLM V1: A Major Upgrade to vLLM’s Core Architecture\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"vLLM Team\",\"codeUrl\":\"https://github.com/vllm-project/vllm\",\"summary\":\"vLLM 官方技术文章，介绍 V1 对调度、KV 管理、执行循环、输入准备与 API 服务的统一重构。\",\"abstract\":\"\",\"sourceUrl\":\"https://vllm.ai/blog/2025-01-27-v1-alpha-release\"},{\"id\":\"vllm-kv-connector\",\"year\":\"2025.9\",\"notes\":\"资料类型：官方工程详解，非学术论文。节点的 2025 仅表示公开技术脉络，未声称 Connector 首次提交日期。\\n关系：以 V1 的 KV 管理和请求生命周期为基础，为 LMCache、NIXL 等具体连接器提供接入点。\\n读法：追踪调度器的外部命中判断、块分配、load/store 回调与 P/D 两侧的数据流。\\n取舍：连接器是接口；端到端收益取决于传输实现、命中率和调度。\",\"title\":\"Inside vLLM: Anatomy of a High-Throughput LLM Inference System\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"vLLM Project\",\"codeUrl\":\"https://github.com/vllm-project/vllm\",\"summary\":\"官方系统详解，解释 V1 的调度、缓存与 KV Connector 在 Prefill/Decode 分离时如何加载、保存及传输 KV。\",\"abstract\":\"\",\"sourceUrl\":\"https://vllm.ai/blog/2025-09-05-anatomy-of-vllm\"},{\"id\":\"vllm-offloading\",\"year\":\"2026.1\",\"notes\":\"资料类型：官方工程分析，非学术论文。\\n关系：在 KV Connector 的读写接口上实现 GPU/CPU 分层缓存。\\n读法：关注异步加载/保存、预填充重算与传输成本、跨层块物理布局。\\n取舍：缓存命中和传输带宽决定收益；文章中的加速数字对应特定硬件与负载。\",\"title\":\"Inside vLLM’s New KV Offloading Connector: Smarter Memory Transfer for Maximizing Inference Throughput\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"vLLM Project\",\"codeUrl\":\"https://github.com/vllm-project/vllm\",\"summary\":\"介绍异步 KV Connector 的 CPU DRAM 卸载，以及连续物理块布局、DMA 传输粒度与 GPU 计算重叠的取舍。\",\"abstract\":\"\",\"sourceUrl\":\"https://vllm.ai/blog/2026-01-08-kv-offloading-connector\"},{\"id\":\"vllm-bidirectional-kv\",\"year\":\"2026.10\",\"notes\":\"资料类型：官方工程文章，非学术论文。\\n关系：在单向 P→D 传输的基础上增加 D→P 回传及缓存感知路由。\\n读法：看块保留 TTL、路由元数据、回传阈值、重算与传输的 break-even。\\n限制：2026.10 新近发布，文中基准仅覆盖所述模型、硬件和 1P1D 设置，需更多独立评估。\",\"title\":\"Improve TTFT for Multi-Turn Agentic Workloads with Bi-Directional KV Transfer in vLLM\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Sunita Nadampalli\",\"codeUrl\":\"https://github.com/vllm-project/vllm\",\"summary\":\"扩展 NIXL KV Connector，让 Prefill 节点从 Decode 节点取回上轮生成的 KV，减少多轮 Agent 会话对历史内容的重复预填充。\",\"abstract\":\"\",\"sourceUrl\":\"https://vllm.ai/blog/2026-10-12-bidirectional-kvxfer-multiturn-agentic-workload\"},{\"id\":\"flashinfer-vllm-related\",\"year\":\"2025.1\",\"notes\":\"位置：关联阅读；FlashInfer 是跨引擎内核层，不能简单画作 vLLM 的一个版本。\\n读法：比较 PagedAttention 的块管理与 FlashInfer 的块稀疏/可组合 kernel 接口及 CUDA Graph 兼容性。\",\"title\":\"FlashInfer: Efficient and Customizable Attention Engine for LLM Inference Serving\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Zihao Ye 等\",\"codeUrl\":\"https://github.com/flashinfer-ai/flashinfer\",\"summary\":\"为分页及其他 KV 布局提供可组合注意力内核、JIT 模板与负载均衡调度；集成于 vLLM、SGLang 等推理引擎。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2501.01005\"},{\"id\":\"sarathi-serve-vllm-related\",\"year\":\"2024.3\",\"notes\":\"位置：关联阅读；Sarathi-Serve 是并行发展的独立系统，不是 vLLM V1 的直接前身。\\n读法：比较 chunked prefill 的调度目标、tail latency 与吞吐，再回看 V1 的统一 token 预算调度。\",\"title\":\"Taming Throughput-Latency Tradeoff in LLM Inference with Sarathi-Serve\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Amey Agrawal 等\",\"codeUrl\":\"https://github.com/microsoft/sarathi-serve\",\"summary\":\"独立服务系统通过 chunked prefill 与无停顿调度改善 prefill/decode 混合批处理，并以 vLLM 为重要对照。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2403.02310\"},{\"id\":\"preble-vllm-related\",\"year\":\"2024.5\",\"notes\":\"位置：关联阅读；Preble 是跨引擎的前缀感知调度层，不是 vLLM 自身的缓存实现。\\n读法：关注全局前缀状态、路由/负载平衡以及跨实例命中和迁移成本。\",\"title\":\"Preble: Efficient Distributed Prompt Scheduling for LLM Serving\",\"hasPdf\":false,\"status\":\"unread\",\"authors\":\"Vikranth Srivatsa 等\",\"codeUrl\":\"\",\"summary\":\"跨 GPU 追踪共享前缀并据此调度请求，将前缀缓存复用从单实例扩展到分布式服务；支持 vLLM 和 SGLang 后端。\",\"abstract\":\"\",\"sourceUrl\":\"https://arxiv.org/abs/2407.00023\"},{\"id\":\"paper-ba84a7ae-3863-4dcb-aff0-25723f670d1a\",\"year\":\"2024.7\",\"notes\":\"\",\"title\":\"Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving\",\"hasPdf\":true,\"status\":\"unread\",\"authors\":\"Ruoyu Qin, Zheming Li, Weiran He, Mingxing Zhang, Yongwei Wu, Weimin Zheng, Xinran Xu\",\"codeUrl\":\"https://github.com/kvcache-ai/Mooncake\",\"summary\":\"Mooncake 是 Moonshot AI 为 Kimi 构建的以 KVCache 为中心的分离式 LLM 服务架构：将 prefill 与 decoding 集群分离，并把 GPU 集群中闲置的 CPU、DRAM、SSD 组织成分离式 KVCache 池，通过全局调度器 Conductor 在满足 TTFT/TBT SLO 的前提下最大化有效吞吐。针对过载场景提出基于预测的提前拒绝策略，并开源了真实请求 trace。\",\"abstract\":\"Mooncake is the serving platform for Kimi, a leading LLM service provided by Moonshot AI. It features a KVCache-centric disaggregated architecture that separates the prefill and decoding clusters. It also leverages the underutilized CPU, DRAM, and SSD resources of the GPU cluster to implement a disaggregated cache of KVCache. The core of Mooncake is its KVCache-centric scheduler, which balances maximizing overall effective throughput while meeting latency-related Service Level Objectives (SLOs). Unlike traditional studies that assume all requests will be processed, Mooncake faces challenges due to highly overloaded scenarios. To mitigate these, we developed a prediction-based early rejection policy. Experiments show that Mooncake excels in long-context scenarios. Compared to the baseline method, Mooncake can achieve up to a 525% increase in throughput in certain simulated scenarios while adhering to SLOs. Under real workloads, Mooncake\'s innovative architecture enables Kimi to handle 75% more requests.\",\"sourceUrl\":\"\"}],\"version\":3,\"taxonomy\":[{\"id\":\"request\",\"name\":\"请求调度\",\"tags\":[{\"id\":\"request-batching\",\"name\":\"批处理策略\",\"english\":\"Batching Strategies\"},{\"id\":\"request-slo\",\"name\":\"延迟约束调度\",\"english\":\"SLO-aware Scheduling\"},{\"id\":\"request-admission\",\"name\":\"抢占与准入控制\",\"english\":\"Preemption & Admission Control\"},{\"id\":\"request-workload\",\"name\":\"负载感知调度\",\"english\":\"Workload-aware Scheduling\"}],\"color\":\"#16838d\",\"english\":\"Request Scheduling\"},{\"id\":\"kv\",\"name\":\"KV 缓存管理\",\"tags\":[{\"id\":\"kv-allocation\",\"name\":\"内存分配\",\"english\":\"Memory Allocation\"},{\"id\":\"kv-reuse\",\"name\":\"缓存复用\",\"english\":\"Cache Reuse\"},{\"id\":\"kv-offloading\",\"name\":\"驱逐与卸载\",\"english\":\"Cache Eviction & Offloading\"},{\"id\":\"kv-compression\",\"name\":\"缓存压缩\",\"english\":\"Cache Compression\"},{\"id\":\"kv-prefetch\",\"name\":\"缓存迁移与预取\",\"english\":\"Cache Migration & Prefetching\"}],\"color\":\"#7653b7\",\"english\":\"KV Cache Management\"},{\"id\":\"acceleration\",\"name\":\"推理加速\",\"tags\":[{\"id\":\"accel-kernel\",\"name\":\"算子优化\",\"english\":\"Attention & Kernel Optimization\"},{\"id\":\"accel-speculative\",\"name\":\"投机解码\",\"english\":\"Speculative Decoding\"},{\"id\":\"accel-quantization\",\"name\":\"量化加速\",\"english\":\"Quantization\"},{\"id\":\"accel-codesign\",\"name\":\"算法与系统协同优化\",\"english\":\"Algorithm-System Co-design\"}],\"color\":\"#c05d2f\",\"english\":\"Inference Acceleration\"},{\"id\":\"distributed\",\"name\":\"分布式推理\",\"tags\":[{\"id\":\"dist-parallelism\",\"name\":\"模型并行\",\"english\":\"Model Parallelism\"},{\"id\":\"dist-pd\",\"name\":\"PD 分离\",\"english\":\"Prefill-Decode Disaggregation\"},{\"id\":\"dist-communication\",\"name\":\"通信优化\",\"english\":\"Communication Optimization\"},{\"id\":\"dist-kv\",\"name\":\"分布式 KV 缓存\",\"english\":\"Distributed KV Cache\"}],\"color\":\"#386ac4\",\"english\":\"Distributed Serving\"},{\"id\":\"cluster\",\"name\":\"集群调度与资源管理\",\"tags\":[{\"id\":\"cluster-routing\",\"name\":\"请求路由\",\"english\":\"Request Routing\"},{\"id\":\"cluster-allocation\",\"name\":\"资源分配\",\"english\":\"Resource Allocation\"},{\"id\":\"cluster-autoscaling\",\"name\":\"弹性扩缩容\",\"english\":\"Autoscaling\"},