INSERT INTO paper_imports (id, filename, status, result, error_text, created_at, updated_at) VALUES ('ba84a7ae-3863-4dcb-aff0-25723f670d1a', '15.Mooncake.pdf', 'done', '{\"title\":\"Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving\",\"action\":\"created\",\"nodeId\":\"node-ba84a7ae-3863-4dcb-aff0-25723f670d1a\",\"reason\":\"论文明确以 prefill/decode 分离（DistServe 等）为出发点并在此基础上把 KVCache 调度作为核心，属于对 PD 分离路线的直接推进，故挂在 DistServe 之下并继承其 PD 分离 tag。\",\"paperId\":\"paper-ba84a7ae-3863-4dcb-aff0-25723f670d1a\",\"evidence\":\"many researchers [ 7 , 8 , 9 ] have suggested separating prefill servers from decoding servers because these two stages of LLM serving have very different computational characteristics, in which the KVCache shifts with requests moving from prefill to decoding servers. Building on this idea, we found that the scheduling of KVCache is central to LLM serving scheduling.\",\"addedLink\":true,\"addedTagId\":null,\"confidence\":0.75,\"addedNodeId\":\"node-ba84a7ae-3863-4dcb-aff0-25723f670d1a\",\"createdNode\":{\"id\":\"node-ba84a7ae-3863-4dcb-aff0-25723f670d1a\",\"time\":\"2024.7\",\"order\":1,\"tagId\":\"pd\",\"title\":\"Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving\",\"dabbled\":false,\"parentId\":\"distserve\",\"description\":\"Mooncake 是 Moonshot AI 为 Kimi 构建的以 KVCache 为中心的分离式 LLM 服务架构：将 prefill 与 decoding 集群分离，并把 GPU 集群中闲置的 CPU、DRAM、SSD 组织成分离式 KVCache 池，通过全局调度器 Conductor 在满足 TTFT/TBT SLO 的前提下最大化有效吞吐。针对过载场景提出基于预测的提前拒绝策略，并开源了真实请求 trace。\"},\"relationship\":\"DistServe 提出把 prefill 与 decode 放到不同 GPU 上分别优化 TTFT 与 TPOT；Mooncake 沿用这一 PD 分离部署形态，但把调度中心从请求负载转移到 KVCache 本身：将集群闲置 CPU/DRAM/SSD 组织成分离式 KVCache 池，由全局 Conductor 按前缀命中长度、传输时间与排队时间选择 prefill/decode 实例，并针对过载场景加入基于预测的提前拒绝。\"}', NULL, '2026-10-14 22:24:29.870', '2026-10-14 22:46:23.986');
